import json, re
from collections import defaultdict, Counter
from datetime import datetime

rows = [json.loads(line) for line in open('commits.jsonl', encoding='utf-8') if line.strip()]

HEADER = re.compile(r'^([a-z]+)(?:\(([^()\s]+)\))?(!)?: (.+)$')

# Revert commits and the commits they name.
reverts = set()
reverted = set()
for r in rows:
    head = r['message'].splitlines()[0]
    if head.startswith('Revert "'):
        reverts.add(r['hash'])
        for line in r['message'].splitlines()[1:]:
            m = re.fullmatch(r'This reverts commit ([0-9a-f]+)\.', line)
            if m:
                reverted.add(m.group(1))

def is_reverted(r):
    h = r['hash']
    return h in reverts or any(h.startswith(t) or t.startswith(h) for t in reverted)

# .mailmap: proper identity first, old email second.
mailmap = {}
for line in open('.mailmap', encoding='utf-8'):
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    m = re.fullmatch(r'(.+?)\s*<([^>]+)>\s*<([^>]+)>', line)
    if m:
        name, proper_email, old_email = m.groups()
        mailmap[proper_email] = name
        mailmap[old_email] = name

commits = []
for r in rows:
    if is_reverted(r):
        continue
    m = HEADER.fullmatch(r['message'].splitlines()[0])
    if not m:
        continue
    kind, scope, bang, summary = m.groups()
    scope = scope or 'general'
    if scope == 'deps':
        scope = 'dependencies'
    breaking = bool(bang)
    if not breaking and kind not in ('feat', 'fix', 'perf'):
        continue
    if scope == 'internal' and not breaking:
        continue

    section = 'Breaking changes' if breaking else {
        'feat': 'Features', 'fix': 'Fixes', 'perf': 'Features'
    }[kind]

    summary = summary[0].upper() + summary[1:] if summary else summary
    if summary.endswith('.'):
        summary = summary[:-1]
    if kind == 'perf':
        summary += ' [perf]'

    refs = []
    if kind == 'fix':
        for line in r['message'].splitlines()[1:]:
            n = re.fullmatch(r'Fixes #(\d+)', line)
            if n:
                refs.append(n.group(1))

    commits.append({
        'hash': r['hash'],
        'author': r['author'],
        'email': r['email'],
        'date': datetime.fromisoformat(r['date']),
        'message': r['message'],
        'kind': kind,
        'scope': scope,
        'summary': summary,
        'refs': refs,
        'section': section,
    })

# Merge entries with the same section, scope and final summary.
groups = defaultdict(list)
for c in commits:
    groups[(c['section'], c['scope'], c['summary'])].append(c)

entries = []
for (section, scope, summary), group in groups.items():
    group.sort(key=lambda c: c['date'], reverse=True)
    refs = []
    for c in group:
        for n in c['refs']:
            if n not in refs:
                refs.append(n)
    hashes = [c['hash'][:7] for c in group]
    entries.append({
        'section': section,
        'scope': scope,
        'summary': summary,
        'refs': refs,
        'hashes': hashes,
        'date': group[0]['date'],
    })

for e in entries:
    start = f"- **{e['scope']}:** "
    ref_text = ''.join(f' (#{n})' for n in e['refs'])
    suffix = ref_text + ' (' + ', '.join(e['hashes']) + ')'
    summary = e['summary']
    if len(start) + len(summary) + len(suffix) > 100:
        max_prefix = 100 - len(start) - 1 - len(suffix)
        summary = summary[:max_prefix].rstrip(' ') + '\u2026'
    e['line'] = start + summary + suffix

# Contributors.
counts = Counter()
authored = set()
for c in commits:
    author_name = mailmap.get(c['email'], c['author'])
    credited = set()
    if not author_name.endswith('[bot]'):
        credited.add(author_name)
        authored.add(author_name)
    for line in c['message'].splitlines()[1:]:
        m = re.match(r'Co-authored-by:\s*(.+?)\s*<([^>]+)>?$', line)
        if m:
            name, email = m.groups()
            name = mailmap.get(email, name)
            if not name.endswith('[bot]'):
                credited.add(name)
    for name in credited:
        counts[name] += 1

contributors = sorted(
    ((name, count) for name, count in counts.items() if name in authored),
    key=lambda item: (-item[1], item[0]),
)

# Assemble sections in the mandated order.
section_order = ['Breaking changes', 'Features', 'Fixes']
blocks = ['# Release 4.2.0']
for title in section_order:
    section_entries = [e for e in entries if e['section'] == title]
    if not section_entries:
        continue
    section_entries.sort(key=lambda e: e['date'], reverse=True)
    section_entries.sort(key=lambda e: e['scope'])
    blocks.append(f"## {title}\n\n" + "\n".join(e['line'] for e in section_entries))

if contributors:
    blocks.append('## Contributors\n\n' + '\n'.join(f'- {name} ({count})' for name, count in contributors))

content = '\n\n'.join(blocks) + '\n'
with open('RELEASE_NOTES.md', 'w', encoding='utf-8', newline='\n') as f:
    f.write(content)

print('entries', len(entries), 'contributors', len(contributors))
print('max line length', max(len(line) for line in content.splitlines()))
print('total lines', len(content.splitlines()))
